{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and applicant rights","requirement":"A landlord may not charge more than the 2026 maximum screening fee of $68.96, must refund unused portions and give the applicant a credit report copy and itemized receipt, and may not charge a fee when no unit is available or to an unselected applicant.","key_value":"$68.96 maximum screening fee (2026)","coverage_conditions":"Statewide limit on tenant screening fees charged to applicants for residential rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"Reusable tenant screening report must be accepted","requirement":"A landlord must use a reusable screening report if the tenant provides one, rather than requiring the applicant to pay for new screening.","key_value":null,"coverage_conditions":"Applies to landlords screening prospective residential tenants who provide a reusable screening report.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley screening fee disclosure and non-refundable fee ban","requirement":"Before collecting a screening fee, an owner must give the applicant a tenant screening fee rights statement and the state maximum fee cap, and may not charge an existing tenant a non-refundable fee to renew or to add or replace a roommate.","key_value":null,"coverage_conditions":"Chapter 13.78 applies to all residential rental agreements regardless of any contractual language in any rental agreement or lease to the contrary.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental agreements in Berkeley"},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the provisions of this chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":"Requires disclosure of the maximum screening fee cap permitted under Cal. Civ. Code § 1950.6(b).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
